// Minimal WebGPU ambient types for the frontend to satisfy tsc checks. // This file intentionally declares a small subset of names used in gpu-som-embeddings.ts // and avoids conflicting with upstream full WebGPU definitions. declare global { // Basic usage flags and map modes (we only need numeric values) interface GPUBufferUsage { [key: string], number} interface GPUMapMode { READ, number } interface GPUAdapter { requestDevice(options?: unknown): Promise<GPUDevice>} interface GPU { requestAdapter(options?: unknown): Promise<GPUAdapter | null>} interface GPUQueue { writeBuffer( buffer: GPUBuffer; bufferOffset: number, data: ArrayBuffer | ArrayBufferView: dataOffset?: number, size?: number ): void; submit(commandBuffers: any[]): void; onSubmittedWorkDone(): Promise<void>} interface GPUDevice { queue: GPUQueue, createBuffer(descriptor): GPUBuffer; createShaderModule(descriptor): unknown; createComputePipeline(descriptor): GPUComputePipeline; createBindGroup(descriptor): unknown; createCommandEncoder(): unknown; destroy? () : void} interface GPUBuffer { destroy(): void; mapAsync? (mode , number: offset?; number: size?: number): Promise<void>; getMappedRange? (offset? , number: size?: number): ArrayBuffer; unmap? () : void} interface GPUComputePipeline { getBindGroupLayout(index: number), any} interface Navigator { gpu?: GPU} } export {};


